return results;

const apiResponse = $json;
const plan = $('Resolver mes').item.json;

return {
  json: {
    ...plan,
    month_id: apiResponse.id
  }
};

const apiResponse = $json;
const plan = $('Plan de meses').item.json;
const files = apiResponse.files || [];

return {
  json: {
    ...plan,
    month_id: files.length > 0 ? files[0].id : null,
    needs_create: files.length === 0
  }
};

const MONTH_NAMES = [
  '01 ENERO','02 FEBRERO','03 MARZO','04 ABRIL',
  '05 MAYO','06 JUNIO','07 JULIO','08 AGOSTO',
  '09 SEPTIEMBRE','10 OCTUBRE','11 NOVIEMBRE','12 DICIEMBRE'
];

const PARENTS = [
  { id: '16ZH6DzAI3XXSawNvyVJR-HytjSbb0ar_', label: 'RBS MEDISTORE 2026' }
];

const YEAR = 2026;
const START_MONTH_IDX = 4;
const END_MONTH_IDX = 11;

const items = [];
for (const parent of PARENTS) {
  for (let m = START_MONTH_IDX; m <= END_MONTH_IDX; m++) {
    const lastDay = new Date(YEAR, m + 1, 0).getDate();
    items.push({
      json: {
        parent_id: parent.id,
        parent_label: parent.label,
        month_name: MONTH_NAMES[m],
        last_day: lastDay,
        year: YEAR
      }
    });
  }
}
return items;

const items = $input.all();
if (!items.length || !items[0].json.id) {
  return [{json:{skip:true}}];
}
return items;

const planeRow = $input.first().json;
const dbRecord = $('Tiene registros?1').item.json;

// Si attachment_id no existe en Plane → fue borrado físicamente
// Si is_deleted = true → fue borrado lógicamente
const notFound = !planeRow || !planeRow.attachment_id;
const markedDeleted = planeRow && planeRow.is_deleted === true;
const shouldDelete = notFound || markedDeleted;

return [{json:{
  ...dbRecord,
  should_delete: shouldDelete,
  reason: notFound ? 'not_found' : (markedDeleted ? 'is_deleted' : 'still_exists')
}}];

const planeIssue = $input.first().json;
const dbRecord = $('Tiene registros?').item.json;

const currentName = planeIssue.name || '';
const savedName = dbRecord.issue_name || '';

// Limpiar nombre igual que al subir
let newClean = currentName.replace(/[^a-zA-Z0-9\u00C0-\u017F\s-]/g,'').trim().replace(/\s+/g,'_').substring(0,60);
let oldClean = savedName.replace(/[^a-zA-Z0-9\u00C0-\u017F\s-]/g,'').trim().replace(/\s+/g,'_').substring(0,60);

const nameChanged = newClean !== oldClean && newClean.length > 0 && oldClean.length > 0;

// Reconstruir nuevo nombre de archivo
const oldFileName = dbRecord.drive_file_name || '';
const ext = oldFileName.split('.').pop() || '';
const date = oldFileName.match(/\d{4}-\d{2}-\d{2}/) ? oldFileName.match(/\d{4}-\d{2}-\d{2}/)[0] : new Date().toISOString().split('T')[0];
const newFileName = `${newClean}_${date}.${ext}`;

return [{json:{
  ...dbRecord,
  current_issue_name: currentName,
  name_changed: nameChanged,
  new_file_name: newFileName,
  new_clean_name: newClean
}}];

const items = $input.all();
if (!items.length || !items[0].json.id) {
  return [{json:{skip:true}}];
}
return items;

const ROUTING = {
  default: { id: '16ZH6DzAI3XXSawNvyVJR-HytjSbb0ar_', label: 'RBS MEDISTORE 2026' },
  byLabel: {
    'rbs medistore 2026': { id: '16ZH6DzAI3XXSawNvyVJR-HytjSbb0ar_', label: 'RBS MEDISTORE 2026' }
  }
};

const labelsResponse = $('Obtener labels').first().json;
const labelsArray = Array.isArray(labelsResponse) ? labelsResponse : (labelsResponse.results || []);
const labelIdToName = {};
for (const label of labelsArray) {
  if (label && label.id && label.name) {
    labelIdToName[label.id] = label.name.toLowerCase().trim();
  }
}

const issues = $input.first().json.results || [];
const processed = [];
const MN = ['01 ENERO','02 FEBRERO','03 MARZO','04 ABRIL','05 MAYO','06 JUNIO','07 JULIO','08 AGOSTO','09 SEPTIEMBRE','10 OCTUBRE','11 NOVIEMBRE','12 DICIEMBRE'];

for (const issue of issues) {
  if (!issue.completed_at) continue;
  const d = new Date(issue.completed_at);
  const day = d.getDate(), month = d.getMonth(), year = d.getFullYear();
  const lastDay = new Date(year, month+1, 0).getDate();
  const q = day <= 15 ? '1-15' : `16-${lastDay}`;
  let cn = issue.name.replace(/[^a-zA-Z0-9\u00C0-\u017F\s-]/g,'').trim().replace(/\s+/g,'_').substring(0,60);

  const issueLabels = (issue.labels || []).map(lid => labelIdToName[lid]).filter(Boolean);
  let target = ROUTING.default;
  for (const lblName of issueLabels) {
    if (ROUTING.byLabel[lblName]) {
      target = ROUTING.byLabel[lblName];
      break;
    }
  }

  processed.push({
    json: {
      issue_id: issue.id,
      issue_name: issue.name,
      clean_name: cn,
      folder_month: MN[month],
      folder_quincena: q,
      created_by: issue.created_by || '',
      target_parent_id: target.id,
      target_parent_label: target.label,
      issue_labels_resolved: issueLabels.join(',') || 'none'
    }
  });
}

if (!processed.length) processed.push({json:{skip:true}});
return processed;

const syncedRows = $input.all();
const syncedIds = new Set(syncedRows.map(r => r.json.issue_id).filter(Boolean));

const allIssues = $('Filtrar tareas').all();

const results = [];
for (const item of allIssues) {
  const issue = item.json;
  if (issue.skip) continue;
  results.push({
    json: {
      ...issue,
      already_synced: syncedIds.has(issue.issue_id)
    }
  });
}

return results;

const allAttachments = $input.all();

const syncedIssues = $('Evaluar sync').all();
const issueMap = {};
for (const it of syncedIssues) {
  const j = it.json;
  if (j && j.issue_id && !j.already_synced) {
    issueMap[j.issue_id] = j;
  }
}

const seenAttachments = new Set();
const items = [];
for (const r of allAttachments) {
  const a = r.json;
  if (!a || !a.attachment_id) continue;
  if (seenAttachments.has(a.attachment_id)) continue;
  seenAttachments.add(a.attachment_id);

  const issue = issueMap[a.issue_id_from_db];
  if (!issue) continue;

  const fn = a.original_name || 'archivo';
  const ext = (fn.includes('.') ? fn.split('.').pop() : 'bin').toLowerCase();
  const final_name = `${issue.clean_name}_${new Date().toISOString().split('T')[0]}.${ext}`;

  items.push({json:{
    asset_url: a.asset,
    attachment_id: a.attachment_id,
    final_name,
    uploader: '',
    issue_id: issue.issue_id,
    issue_name: issue.issue_name,
    clean_name: issue.clean_name,
    folder_month: issue.folder_month,
    folder_quincena: issue.folder_quincena,
    target_parent_id: issue.target_parent_id,
    target_parent_label: issue.target_parent_label
  }});
}

if(!items.length) items.push({json:{skip:true}});
return items;

// NIVEL 1: Combos únicos de MES solamente (parent + month)
// Si tenemos 25 items, esto reduce a N (1 por cada parent+mes único)
const items = $input.all();
const uniqueMonths = new Map();

for (const item of items) {
  const j = item.json;
  const key = `${j.target_parent_id}|${j.folder_month}`;
  if (!uniqueMonths.has(key)) {
    uniqueMonths.set(key, {
      target_parent_id: j.target_parent_id,
      target_parent_label: j.target_parent_label,
      folder_month: j.folder_month
    });
  }
}

return Array.from(uniqueMonths.values()).map(c => ({json: c}));

const apiResponse = $json;
const files = apiResponse.files || [];
const monthId = files.length > 0 ? files[0].id : null;

const original = $('Combos únicos de mes').itemMatching($itemIndex).json;

return {
  json: {
    ...original,
    month_folder_id: monthId
  }
};

const input = $json;
const monthId = input.id || input.month_folder_id;

const original = $('Combos únicos de mes').itemMatching($itemIndex).json;

return {
  json: {
    ...original,
    month_folder_id: monthId
  }
};

// NIVEL 2: Expandir a combos únicos de QUINCENA
// Tomamos los meses resueltos y los cruzamos con las quincenas únicas necesarias
const monthsResolved = $input.all();
const monthMap = {};
for (const m of monthsResolved) {
  const j = m.json;
  const key = `${j.target_parent_id}|${j.folder_month}`;
  monthMap[key] = j.month_folder_id;
}

// Sacar combos únicos de quincena de los items originales
const originals = $('Preparar archivos').all();
const uniqueQuincenas = new Map();

for (const item of originals) {
  const j = item.json;
  if (j.skip) continue;
  const quincenaKey = `${j.target_parent_id}|${j.folder_month}|${j.folder_quincena}`;
  if (!uniqueQuincenas.has(quincenaKey)) {
    const monthKey = `${j.target_parent_id}|${j.folder_month}`;
    uniqueQuincenas.set(quincenaKey, {
      target_parent_id: j.target_parent_id,
      target_parent_label: j.target_parent_label,
      folder_month: j.folder_month,
      folder_quincena: j.folder_quincena,
      month_folder_id: monthMap[monthKey]
    });
  }
}

return Array.from(uniqueQuincenas.values()).map(c => ({json: c}));

const apiResponse = $json;
const files = apiResponse.files || [];
const quincenaId = files.length > 0 ? files[0].id : null;

const original = $('Combos únicos de quincena').itemMatching($itemIndex).json;

return {
  json: {
    ...original,
    quincena_folder_id: quincenaId
  }
};

const input = $json;
const quincenaId = input.id || input.quincena_folder_id;

const original = $('Combos únicos de quincena').itemMatching($itemIndex).json;

return {
  json: {
    ...original,
    quincena_folder_id: quincenaId
  }
};

// Mapear combos resueltos a los items originales
const resolved = $input.all();
const comboMap = {};
for (const item of resolved) {
  const j = item.json;
  const key = `${j.target_parent_id}|${j.folder_month}|${j.folder_quincena}`;
  comboMap[key] = {
    month_folder_id: j.month_folder_id,
    quincena_folder_id: j.quincena_folder_id
  };
}

const originals = $('Preparar archivos').all();
const output = [];
for (const item of originals) {
  const j = item.json;
  if (j.skip) continue;
  const key = `${j.target_parent_id}|${j.folder_month}|${j.folder_quincena}`;
  const ids = comboMap[key];
  if (!ids) continue;
  output.push({
    json: {
      ...j,
      month_folder_id: ids.month_folder_id,
      quincena_folder_id: ids.quincena_folder_id
    }
  });
}

return output;

const driveResp = $json;
const ctx = $('Aplicar carpetas a items').itemMatching($itemIndex).json;

return {
  json: {
    ...ctx,
    drive_file_id: driveResp.id,
    drive_file_link: driveResp.webViewLink || `https://drive.google.com/file/d/${driveResp.id}/view`,
    drive_file_name_actual: driveResp.name
  }
};

const all = $input.all();
const seen = new Set();
const unique = [];

for (const item of all) {
  const id = item.json.issue_id;
  if (!id) continue;
  if (!seen.has(id)) {
    seen.add(id);
    unique.push({ json: item.json });
  }
}

return unique;

const ctx = $('Dedupe por issue').itemMatching($itemIndex).json;

const current = $json;
const planeError = current && current.error ? current.error.message : null;
const linkAlreadyExists = planeError && planeError.includes('URL already exists');

return {
  json: {
    ...ctx,
    plane_link_status: planeError ? (linkAlreadyExists ? 'already_existed' : 'error') : 'created'
  }
};
